cd /home/daniel/ui-work/runs/202610271-as/sandbox/officehq-angular-spring/src/main/frontend/src/app; python3 - <<'EOF'
p='features/claims/claims.ts'; s=open(p).read()
old=s[s.index("/**\n * The late charge in cents on an overdue claim"):s.index("/** Overdue: OPEN or PENDING")]
new='''/**
 * The late charge in cents on an overdue claim with the given figure, worked out per 30-day boundary: for each full
 * 30 days past its due-by, the late percent in force on that boundary date (the due-by plus 30, 60, 90 ... days) of
 * it, rounded like a due, and the charges added up; 0 when not overdue or a correction. Never bound by a statement.
 */
export function lateChargeCents(c: Claim, figureCents: number, late: Late, halfUp: boolean): number {
  if (late.today === null || isCorrection(c) || !isOverdue(c, late.today)) return 0;
  const dueBy = Date.parse(`${c.dueBy}T00:00:00Z`);
  let total = 0;
  for (let step = 1; ; step++) {
    const boundary = new Date(dueBy + step * 30 * 86_400_000).toISOString().slice(0, 10);
    if (boundary > late.today) return total;
    total += dueCents(figureCents, late.pctOn(boundary), halfUp);
  }
}

'''
s=s.replace(old,new)
s=s.replace(" * with its late charge (by the late percent in force on its date) on top;"," * with its late charge (by the late percent in force on each 30-day boundary) on top;")
open(p,'w').write(s)
EOF
sed -i 's|an overdue claim.s due gains the one in force on its date of its figure every full 30 days. \*/|an overdue claim'"'"'s due gains, for each full 30 days, the one in force on that boundary date of its figure. */|' core/session.ts; sed -n 54p core/session.ts; grep -rn "lateChargeCents\|pctOn(c.date)" --include=*.ts . | grep -v "claims.ts:1[67]"

